from collections import deque

edges = {
    "kim(피싱된 직원)": [("PC-042", "로그인 세션")],
    "PC-042": [("svc_backup", "세션에 남은 계정")],
    "svc_backup": [("SRV-FILE", "로컬 관리자")],
    "SRV-FILE": [("admin_lee", "세션에 남은 계정")],
    "admin_lee": [("Domain Admins", "그룹 구성원")],
}

def path(src, dst):
    q, prev = deque([src]), {src: None}
    while q:
        n = q.popleft()
        if n == dst:
            out = []
            while prev[n]:
                p, why = prev[n]
                out.append(f"{p} --{why}--> {n}")
                n = p
            return out[::-1]
        for m, why in edges.get(n, []):
            if m not in prev:
                prev[m] = (n, why)
                q.append(m)

for step in path("kim(피싱된 직원)", "Domain Admins"):
    print(step)

